import { readFileSync } from "node:fs";
import path from "node:path";
export function ownerOf(root) {
  const order = readFileSync(path.join(root, "process/modules/order.txt"), "utf8").trim().split("\n");
  const claims = order.map((m) => { const j = JSON.parse(readFileSync(path.join(root, `process/modules/${m}.json`), "utf8")); return [m, [...(j.files || []), ...(j.tests || [])]]; });
  const owner = (f) => { let best = null, len = -1; for (const [m, ps] of claims) for (const p of ps) { if ((f === p || (p.endsWith("/") && f.startsWith(p))) && p.length > len) { best = m; len = p.length; } } return best; };
  return { owner, order, pos: (m) => order.indexOf(m) + 1 };
}

