// Import graph of every test file run by the test command, by esbuild's parser (metafile), in a given checkout.
//   node graph.mjs <checkout> <out.json>
import { readFileSync, writeFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
const ROOT = path.resolve(process.argv[2]);
const { build } = await import(path.join(ROOT, "bio-plane/node_modules/esbuild/lib/main.js"));
process.chdir(ROOT);
const order = readFileSync("process/modules/order.txt", "utf8").trim().split("\n");
const claims = order.map((m) => { const j = JSON.parse(readFileSync(`process/modules/${m}.json`, "utf8")); return [m, [...(j.files || []), ...(j.tests || [])]]; });
export function owner(f) { let best = null, len = -1; for (const [m, ps] of claims) for (const p of ps) { if ((f === p || (p.endsWith("/") && f.startsWith(p))) && p.length > len) { best = m; len = p.length; } } return best; }
const SKIP = new Set(["node_modules", ".git", "dist", "release", "vendor"]);
const tests = [];
(function walk(d) { for (const n of readdirSync(d)) { if (SKIP.has(n)) continue; const p = path.join(d, n); let st; try { st = statSync(p); } catch { continue; } if (st.isDirectory()) walk(p); else if (/\.test\.mjs$/.test(n)) tests.push(p); } })(".");
tests.sort();
const inputs = {}; const failed = [];
// one build per chunk of entries; a file that does not parse is recorded, not hidden
for (let i = 0; i < tests.length; i += 60) {
  const chunk = tests.slice(i, i + 60);
  try {
    const r = await build({ entryPoints: chunk, bundle: true, splitting: true, write: false, metafile: true, format: "esm", platform: "node", packages: "external",
      external: ["cloudflare:workers", "node:*"], outdir: "/tmp/none", logLevel: "silent", absWorkingDir: ROOT, loader: { ".txt": "text", ".html": "text", ".node": "empty" } });
    for (const [p, v] of Object.entries(r.metafile.inputs)) inputs[p] = v.imports.filter((x) => !x.external).map((x) => x.path);
  } catch (e) {
    for (const t of chunk) { try {
      const r = await build({ entryPoints: [t], bundle: true, splitting: true, write: false, metafile: true, format: "esm", platform: "node", packages: "external",
        external: ["cloudflare:workers", "node:*"], outdir: "/tmp/none", logLevel: "silent", absWorkingDir: ROOT, loader: { ".txt": "text", ".html": "text", ".node": "empty" } });
      for (const [p, v] of Object.entries(r.metafile.inputs)) inputs[p] = v.imports.filter((x) => !x.external).map((x) => x.path);
    } catch (e2) { failed.push({ test: t, error: String(e2.message).slice(0, 300) }); } }
  }
}
const owners = {}; for (const p of Object.keys(inputs)) owners[p] = owner(p);
writeFileSync(process.argv[3], JSON.stringify({ root: ROOT, tests, inputs, owners, order, failed }));
console.log("tests", tests.length, "inputs", Object.keys(inputs).length, "failed", failed.length, failed.slice(0, 5));

scriptsText.mark.mjs:
// Preload for the trace of deliverOwedRender: no file is changed. In Node the module's source is given one extra statement as it is
// loaded (module.registerHooks); for workerd, Miniflare's own read of the file is answered with the same statement added.
// The statement: globalThis.__t17 ? globalThis.__t17() : console.log("@@T17-REACHED@@");
import module, { syncBuiltinESMExports } from "node:module";
import fs from "node:fs";
const TARGET = "/bio-plane/src/control-plane/index.mjs";
const HEAD = 'export async function deliverOwedRender({ ctx, env, storeName = "bio", answer, session } = {}) {';
const ADD = ' globalThis.__t17 ? globalThis.__t17() : console.log("@@T17-REACHED@@");';
const inject = (src) => { const at = src.indexOf(HEAD); if (at < 0) { note("HEAD-NOT-FOUND"); return src; } return src.slice(0, at + HEAD.length) + ADD + src.slice(at + HEAD.length); };
const real = { appendFileSync: fs.appendFileSync, readFileSync: fs.readFileSync };
const OUT = process.env.T17_OUT;
function note(what) { if (!OUT) return; try { real.appendFileSync(OUT, `${what} pid=${process.pid}\n`); } catch { /* no trace file */ } }
globalThis.__t17 = () => note("REACHED-NODE");
module.registerHooks({ load(url, context, nextLoad) {
  const r = nextLoad(url, context);
  if (url.endsWith(TARGET) && r.source != null) { note("LOADED-NODE"); return { ...r, source: inject(String(r.source)) }; }
  return r;
} });
// Miniflare reads each module of the Worker with fs.readFileSync(path, "utf8"); only those reads are answered with the added statement
fs.readFileSync = function (p, ...rest) {
  const out = real.readFileSync.call(this, p, ...rest);
  try {
    if (typeof p === "string" && p.endsWith(TARGET) && /[\\/]miniflare[\\/]/.test(String(new Error().stack))) { note("LOADED-WORKERD"); return typeof out === "string" ? inject(out) : Buffer.from(inject(out.toString("utf8"))); }
  } catch { /* the plain read */ }
  return out;
};
syncBuiltinESMExports();

scriptsText.run.mjs:
// Runs test files one process each, as process.json's test_command runs them, a few at a time, keeping each file's whole output.
//   node run.mjs <checkout> <list.json> <out folder> [--jobs 2] [--timeout 900] [--preload <file>] [--net]
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { spawn } from "node:child_process";
const [checkout, listFile, outDir0] = process.argv.slice(2);
const outDir = path.resolve(outDir0);
const flag = (name) => { const i = process.argv.indexOf(name); return i > 0 ? process.argv[i + 1] : null; };
const JOBS = Number(flag("--jobs") || 2), TIMEOUT = Number(flag("--timeout") || 900) * 1000, PRELOAD = flag("--preload");
const root = path.resolve(checkout);
const cfg = JSON.parse(fs.readFileSync(path.join(root, "process.json"), "utf8"));
const command = cfg.test_command.split(/\s+/);
const files = JSON.parse(fs.readFileSync(listFile, "utf8"));
fs.mkdirSync(path.join(outDir, "logs"), { recursive: true });
const home = path.join(outDir, "home"); fs.mkdirSync(home, { recursive: true });
const tmp = path.join(outDir, "tmp"); fs.mkdirSync(tmp, { recursive: true });
const base = { PATH: process.env.PATH, HOME: home, TMPDIR: tmp, LANG: "C.UTF-8", CI: "true" };
for (let i = 0; i < process.argv.length; i++) if (process.argv[i] === "--env") { const [k, ...v] = process.argv[i + 1].split("="); base[k] = v.join("="); }
if (process.argv.includes("--net")) for (const k of ["HTTPS_PROXY", "https_proxy", "NO_PROXY", "no_proxy", "NODE_EXTRA_CA_CERTS", "SSL_CERT_FILE", "NODE_USE_ENV_PROXY"]) if (process.env[k]) base[k] = process.env[k];
const runsFile = path.join(outDir, "runs.json");
const runs = fs.existsSync(runsFile) ? JSON.parse(fs.readFileSync(runsFile, "utf8")) : [];
const done = new Set(runs.map((r) => r.file));
const todo = files.filter((f) => !done.has(f));
let next = 0, running = 0; const started = Date.now();
const slug = (f) => f.replace(/[^A-Za-z0-9.]+/g, "_");
await new Promise((finish) => {
  if (!todo.length) return finish();
  const pump = () => {
    while (running < JOBS && next < todo.length) {
      const file = todo[next++]; running++;
      const t0 = Date.now(); const log = path.join(outDir, "logs", slug(file) + ".log"); const mark = path.join(outDir, "logs", slug(file) + ".mark");
      const fd = fs.openSync(log, "w");
      const env = { ...base, ...(PRELOAD ? { NODE_OPTIONS: `--import=${PRELOAD}`, T17_OUT: mark } : {}) };
      const child = spawn(process.execPath, [...command.slice(1), file], { cwd: root, env, stdio: ["ignore", fd, fd], detached: true });
      const timer = setTimeout(() => { try { process.kill(-child.pid, "SIGKILL"); } catch { /* gone */ } }, TIMEOUT);
      child.on("close", (code, signal) => {
        clearTimeout(timer); fs.closeSync(fd); running--;
        const out = fs.readFileSync(log, "utf8");
        const num = (k) => { const m = new RegExp(`^(?:#|\u2139) ${k} (\\d+)`, "m").exec(out); return m ? Number(m[1]) : null; };
        // the spec reporter's lines, up to its closing list of failures: a pass, a failure, a skip
        const body = out.split(/^\u2716 failing tests:$/m)[0];
        const subs = [...body.matchAll(/^( *)(\u2714|\u2716|\ufe63) (.*?)(?: \(\d+(?:\.\d+)?ms\))?(?: # .*)?$/gm)].map((m) => ({ depth: m[1].length / 2, mark: m[2] === "\u2714" ? "pass" : m[2] === "\u2716" ? "fail" : "skip", name: m[3] }));
        const marks = fs.existsSync(mark) ? fs.readFileSync(mark, "utf8").trim().split("\n") : [];
        runs.push({ file, code, signal, seconds: Math.round((Date.now() - t0) / 1000), load: os.loadavg().map((x) => +x.toFixed(2)), tests: num("tests"), pass: num("pass"), fail: num("fail"), skipped: num("skipped"), cancelled: num("cancelled"), todo: num("todo"),
          subs, reachedNode: marks.filter((m) => m.startsWith("REACHED-NODE")).length, loadedNode: marks.filter((m) => m.startsWith("LOADED-NODE")).length, loadedWorkerd: marks.filter((m) => m.startsWith("LOADED-WORKERD")).length,
          headMissing: marks.filter((m) => m.startsWith("HEAD-NOT-FOUND")).length, reachedWorkerd: (out.match(/@@T17-REACHED@@/g) || []).length });
        fs.writeFileSync(runsFile, JSON.stringify(runs));
        console.log(`${runs.length}/${files.length} ${code === 0 ? "ok  " : signal ? "KILL" : "FAIL"} ${Math.round((Date.now() - t0) / 1000)}s load ${os.loadavg()[0].toFixed(1)} ${file}`);
        if (next >= todo.length && running === 0) finish(); else pump();
      });
    }
  };
  pump();
});
console.log(`done: ${runs.filter((r) => r.code === 0).length} exit 0, ${runs.filter((r) => r.code !== 0).length} not, in ${Math.round((Date.now() - started) / 1000)} s`);

