// Runs each test file first in checkout A (unchanged) and then in checkout B (changed), one after the other, so both runs of a file meet about the same machine load.
//   node pair.mjs <list.json> <out folder> --a <checkout A> --b <checkout B> [--jobs 2] [--timeout 900]
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { spawn } from "node:child_process";
const [listFile, outDir0] = process.argv.slice(2);
const flag = (name) => { const i = process.argv.indexOf(name); return i > 0 ? process.argv[i + 1] : null; };
const A = path.resolve(flag("--a")), B = flag("--b") ? path.resolve(flag("--b")) : null;
const JOBS = Number(flag("--jobs") || 2), TIMEOUT = Number(flag("--timeout") || 900) * 1000;
const outDir = path.resolve(outDir0);
const cfg = JSON.parse(fs.readFileSync(path.join(A, "process.json"), "utf8"));
const command = cfg.test_command.split(/\s+/);
const files = JSON.parse(fs.readFileSync(listFile, "utf8"));
for (const d of ["logs", "home", "tmp"]) fs.mkdirSync(path.join(outDir, d), { recursive: true });
const env = { PATH: process.env.PATH, HOME: path.join(outDir, "home"), TMPDIR: path.join(outDir, "tmp"), LANG: "C.UTF-8", CI: "true" };
for (let i = 0; i < process.argv.length; i++) if (process.argv[i] === "--env") { const [k, ...v] = process.argv[i + 1].split("="); env[k] = v.join("="); }
const runsFile = path.join(outDir, "runs.json");
const runs = fs.existsSync(runsFile) ? JSON.parse(fs.readFileSync(runsFile, "utf8")) : [];
const done = new Set(runs.map((r) => r.file));
const todo = files.filter((f) => !done.has(f));
const slug = (f) => f.replace(/[^A-Za-z0-9.]+/g, "_");
function one(root, file, tag) {
  return new Promise((resolve) => {
    const t0 = Date.now(); const log = path.join(outDir, "logs", `${slug(file)}.${tag}.log`); const fd = fs.openSync(log, "w");
    const child = spawn(process.execPath, [...command.slice(1), file], { cwd: root, env, stdio: ["ignore", fd, fd], detached: true });
