const PROJECT = "PROJ-2026-0001";
const WHO = { author: "ann", actorMemberId: "ann", actorIdentity: "member:ann", actorViewer: "member:ann" };

async function fresh(input) {
  const r = await record();
  for (const b of input.held) r.objects.set(`bio/captures/${hex(b)}`, b);
  // the author takes part in the project the document is filed under (r124-owed-render.test.mjs's `owing` does the same)
  r.ctx.storage.sql.exec(`INSERT INTO project_participants (project_id, member_id, state, owner, created, updated) VALUES (?, ?, 'active', 0, '2026-10-22T00:00:00Z', '2026-10-22T00:00:00Z')`, PROJECT, "ann");
