}

// A. the screen's functions as the background delivery runs them: the real deliverOwedRender over a real record
async function viaDelivery(input) {
  const { r, sent } = await fresh(input);
  const session = "sess-compose";
  captureOf(r.ctx).saveCaptureSession({ session, locator: input.doc.locator || "https://example.org/shell.html", primarySha: "f".repeat(64), primaryFile: "shell.html", base: "https://example.org/shell.html",
    state: { opened_by: "ann", project: PROJECT, queue: [], render_pending: { body: {} } } });
  const added = [];
  const env = { ...r.env, STORE: { idFromName: (n) => n, get: () => ({ fetch: async (req) => { added.push(String(req.url ?? req)); return new Response(JSON.stringify({ ok: true, result: { ok: true } })); } }) } };
  const out = await deliverOwedRender({ ctx: r.ctx, env, storeName: "bio", answer: { ok: true, document: input.doc, ...(input.answerReading ? { reading: input.answerReading } : {}) }, session });
