}
// A'. the same two functions called directly with a test's kit (as r124-owed-render.test.mjs's `screen` kit), words unresolved
async function viaScreenDirect(input) {
  const { r, sent } = await fresh(input);
  const cs = { now: () => Date.now(), digest: async (t) => hex(t), w: (k) => k, date: (d) => d,
    call: async (op, { query = {}, body } = {}) => (op === "allocid" ? { ok: true, ...recordOf(r.ctx).allocId(query.prefix, query.year) } : promotionOf(r.ctx).promote({ ...body, ...WHO })) };
  const title = CAPTURE_SCREEN.parts.titleOf(cs, { reading: input.answerReading, doc: input.doc, address: String(input.doc.locator || "") });
  const out = await CAPTURE_SCREEN.parts.promoteDocument(cs, { doc: input.doc, title, locator: String(input.doc.locator || ""), project: PROJECT });
  return { answer: out, sent };
}
// B. control-plane/archive.mjs: promoteArchive over the record's own routes (as archive.test.mjs's third test drives it)
async function viaArchive(input) {
  const { r, sent } = await fresh(input);
  const rec = recordOf(r.ctx);
  const stub = { async fetch(req) {
    const u = new URL(req.url);
    if (u.pathname === "/allocid") return reply({ ok: true, result: rec.allocIdOp(u.searchParams.get("prefix"), u.searchParams.get("year")) });
    if (u.pathname === "/promote") return reply({ ok: true, result: promotionOf(r.ctx).promote(await req.json()) });
