  const out = await pullAndFile({ doorbell, promotion: prom, record: recordOf(r.ctx), provenance: provenanceOf(r.ctx), extraction: extractionOf(r.ctx) },
    { knockId: "KNOCK-1", by: "ann", identity: "member:ann", viewer: "member:ann", now: () => Date.now() });
  const { document: _d, ...rest } = out || {};
  return { answer: rest, sent };
