const norm = (pkg) => pkg && ({ ...pkg, snapKey: String(pkg.snapKey).replace(/_[0-9a-f]{8}$/, "_<random8>") });
const result = { instant: new REAL(T).toISOString(), project: PROJECT, who: WHO, inputs: [] };
for (const input of INPUTS) {
  const row = { name: input.name, doc: input.doc, composers: {} };
