// Differences between the packages the composers sent, per input. node compose-diff.mjs <folder with packages.json> [a] [b]
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
const dir = path.resolve(process.argv[2]);
const j = JSON.parse(fs.readFileSync(path.join(dir, "packages.json"), "utf8"));
const pairs = [["delivery", "screenDirect"], ["delivery", "archive"], ["delivery", "pull"], ["archive", "pull"]];
const flat = (v, pre = "", out = {}) => { if (v !== null && typeof v === "object") { if (Array.isArray(v) && !v.length) out[pre] = "[]"; for (const [k, x] of Object.entries(v)) flat(x, pre ? `${pre}.${k}` : k, out); } else out[pre] = v; return out; };
const summary = [];
for (const row of j.inputs) {
  const entry = { input: row.name, pairs: {} };
  for (const [a, b] of pairs) {
    const A = row.composers[a].pkg, B = row.composers[b].pkg; if (!A || !B) { entry.pairs[`${a}|${b}`] = { missing: true }; continue; }
    const d = { same: JSON.stringify(A) === JSON.stringify(B), topKeys: {}, meta: {}, files: {}, register: {} };
    const ka = Object.keys(A).filter((k) => !["files", "meta", "register"].includes(k)), kb = Object.keys(B).filter((k) => !["files", "meta", "register"].includes(k));
    for (const k of new Set([...ka, ...kb])) if (JSON.stringify(A[k]) !== JSON.stringify(B[k])) d.topKeys[k] = [A[k] ?? "(absent)", B[k] ?? "(absent)"];
    const ma = flat(A.meta), mb = flat(B.meta); for (const k of new Set([...Object.keys(ma), ...Object.keys(mb)])) if (ma[k] !== mb[k]) d.meta[k] = [k in ma ? ma[k] : "(absent)", k in mb ? mb[k] : "(absent)"];
    const pa = A.files.map((f) => f.path), pb = B.files.map((f) => f.path);
    d.files.onlyA = pa.filter((p) => !pb.includes(p)); d.files.onlyB = pb.filter((p) => !pa.includes(p)); d.files.differ = {};
    for (const p of pa.filter((x) => pb.includes(x))) { const fa = A.files.find((f) => f.path === p), fb = B.files.find((f) => f.path === p);
      if (JSON.stringify(fa) !== JSON.stringify(fb)) d.files.differ[p] = { bytes: [fa.bytes, fb.bytes], sha256: [fa.sha256, fb.sha256], keys: [Object.keys(fa).join(","), Object.keys(fb).join(",")], textDiffers: fa.text !== fb.text }; }
    const ra = flat(A.register), rb = flat(B.register); for (const k of new Set([...Object.keys(ra), ...Object.keys(rb)])) if (ra[k] !== rb[k]) d.register[k] = [k in ra ? ra[k] : "(absent)", k in rb ? rb[k] : "(absent)"];
    entry.pairs[`${a}|${b}`] = d;
  }
  summary.push(entry);
}
fs.writeFileSync(path.join(dir, "diff.json"), JSON.stringify(summary, null, 1));
for (const e of summary) for (const [k, d] of Object.entries(e.pairs)) console.log(e.input.padEnd(26), k.padEnd(22), d.same ? "IDENTICAL" : `differ: top ${Object.keys(d.topKeys).join(",") || "-"} | meta ${Object.keys(d.meta).join(",") || "-"} | files onlyA ${d.files.onlyA.join(",") || "-"} onlyB ${d.files.onlyB.join(",") || "-"} changed ${Object.keys(d.files.differ).join(",") || "-"} | register ${Object.keys(d.register).join(",") || "-"}`);

