// Background work and UI-owned code. node bg.mjs <checkout>
import { readFileSync, writeFileSync, readdirSync, mkdirSync } from "node:fs";
import path from "node:path";
import { ownerOf } from "./own.mjs";
const ROOT = path.resolve(process.argv[2]);
const { build } = await import(path.join(ROOT, "bio-plane/node_modules/esbuild/lib/main.js"));
const { owner, pos } = ownerOf(ROOT);
const isUI = (f) => { const p = pos(owner(f)); return p >= 176 && p <= 194; };
const common = { bundle: true, write: false, metafile: true, format: "esm", platform: "neutral", external: ["cloudflare:workers", "node:*"], outdir: "/tmp/none", logLevel: "silent", absWorkingDir: ROOT };
const graph = async (entries) => { const r = await build({ ...common, entryPoints: entries }); const g = {}; for (const [p, v] of Object.entries(r.metafile.inputs)) g[p] = v.imports.filter((x) => !x.external).map((x) => x.path); return g; };
const closure = (g, starts, cut = () => false) => { const seen = new Set(); const todo = [...starts]; while (todo.length) { const f = todo.pop(); if (seen.has(f)) continue; seen.add(f); for (const n of g[f] || []) if (!cut(f, n)) todo.push(n); } return seen; };
const src = (d) => readdirSync(path.join(ROOT, "bio-plane/src", d)).filter((n) => n.endsWith(".mjs")).map((n) => `bio-plane/src/${d}/${n}`);
const out = {};
// (a) the import closure of every source file of store-assembly and scheduler
for (const d of ["store-assembly", "scheduler"]) {
  const files = src(d); const g = await graph(files); const c = closure(g, files);
  const ui = [...c].filter(isUI); const mods = [...new Set([...c].map(owner))].sort((a, b) => pos(a) - pos(b));
  out[d] = { entries: files.length, files: c.size, uiFiles: ui, latest: mods.slice(-3).map((m) => `${m}(${pos(m)})`) };
  console.log(`(a) ${d}: ${files.length} source files, closure ${c.size} files, UI-owned files in it: ${ui.length}, latest modules: ${out[d].latest.join(" ")}`);
