// A screen part re-made from its own text, as the page has it (interface-shell toSource: `v.toString()`), then called with a small kit.
import path from "node:path"; import { pathToFileURL } from "node:url"; import { createHash } from "node:crypto";
const CO = path.resolve(process.argv[2]);
const { CAPTURE_SCREEN } = await import(pathToFileURL(path.join(CO, "bio-plane/src/screens-intake/capture.mjs")).href);
const { toSource } = await import(pathToFileURL(path.join(CO, "bio-plane/src/interface-shell/index.mjs")).href);
const hex = (t) => createHash("sha256").update(t).digest("hex");
const sent = [];
const cs = { now: () => Date.parse("2026-11-02T09:30:15Z"), digest: async (t) => hex(t), w: (k) => k, date: (d) => d,
  call: async (op, { body } = {}) => { if (op === "allocid") return { ok: true, id: "INFO-2026-0001" }; sent.push(body); return { ok: true, bundleId: body.bundleId }; } };
const doc = { file: "rendered.html", locator: "https://example.org/rendered.html", capture: { sha256: "a".repeat(64), bytes: 3, encoding: "binary" } };
for (const name of ["titleOf", "promoteDocument"]) {
  const text = toSource(CAPTURE_SCREEN.parts[name]);
  const remade = new Function(`return (${text});`)();   // no module scope: only the text
  try { const out = await remade(cs, { doc, title: "A title", locator: doc.locator, project: "", reading: { title: "A title" }, address: doc.locator }); console.log(name, "from its text:", JSON.stringify(out).slice(0, 120)); }
  catch (e) { console.log(name, "from its text THROWS:", e.name + ": " + e.message); }
}
console.log("promote bodies sent:", sent.length);
